#!/usr/bin/env python3
"""Firebase (FCM) wiring for a Flutter Android project generated by `flutter create`.

Usage (run from the app folder, e.g. apps/parent_app):
    python3 ../../tools/ci/firebase_setup.py android firebase/google-services.json

- If the google-services.json file is missing, does nothing (build stays the same).
- Copies it to android/app/google-services.json.
- Adds the Google services Gradle plugin to the project and app Gradle files.
- Fails loudly if the Gradle layout is not what we expect.
"""
import pathlib
import re
import shutil
import sys

PLUGIN_VERSION = "4.4.2"


def patch_first(path: pathlib.Path, anchor_regex: str, insert_after: str) -> None:
    text = path.read_text(encoding="utf-8")
    if "com.google.gms.google-services" in text:
        return  # already wired (idempotent)
    lines = text.splitlines(keepends=True)
    for i, line in enumerate(lines):
        if re.search(anchor_regex, line):
            lines.insert(i + 1, insert_after + "\n")
            path.write_text("".join(lines), encoding="utf-8")
            return
    sys.exit(f"Firebase setup: anchor not found in {path}")


def main() -> None:
    if len(sys.argv) != 3:
        sys.exit("usage: firebase_setup.py <android_dir> <google-services.json>")
    android = pathlib.Path(sys.argv[1])
    json_src = pathlib.Path(sys.argv[2])

    if not json_src.exists():
        print(f"Firebase: {json_src} nahi mili - Firebase step skip (app bina push ke banegi).")
        return

    shutil.copyfile(json_src, android / "app" / "google-services.json")

    settings = android / "settings.gradle.kts"
    if settings.exists():
        patch_first(
            settings,
            r'id\("com\.android\.application"\)',
            f'    id("com.google.gms.google-services") version "{PLUGIN_VERSION}" apply false',
        )
    else:
        patch_first(
            android / "settings.gradle",
            r"id ['\"]com\.android\.application['\"]",
            f"    id 'com.google.gms.google-services' version '{PLUGIN_VERSION}' apply false",
        )

    app_kts = android / "app" / "build.gradle.kts"
    if app_kts.exists():
        patch_first(
            app_kts,
            r"dev\.flutter\.flutter-gradle-plugin|kotlin-android|org\.jetbrains\.kotlin\.android",
            '    id("com.google.gms.google-services")',
        )
    else:
        patch_first(
            android / "app" / "build.gradle",
            r"dev\.flutter\.flutter-gradle-plugin|kotlin-android|org\.jetbrains\.kotlin\.android",
            "    id 'com.google.gms.google-services'",
        )
    print("Firebase: google-services plugin wired.")


if __name__ == "__main__":
    main()
